// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 round) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != c.owner());
        round = bound(round, 0, 50);

        // Drive distribution through the public entry getTokens (also reachable via receive).
        // Before the call, this caller is not blacklisted, so it may receive tokens.
        vm.assume(!c.blacklist(actor));

        uint256 balBefore = c.balanceOf(actor);
        uint256 distBefore = c.totalDistributed();
        uint256 valueBefore = c.value();
        uint256 remBefore = c.totalRemaining();
        uint256 toGive = valueBefore > remBefore ? remBefore : valueBefore;

        vm.prank(actor);
        c.getTokens();

        uint256 distDelta = c.totalDistributed() - distBefore;
        uint256 balDelta = c.balanceOf(actor) - balBefore;

        // General rule: the recipient's balance increases by exactly the amount
        // accounted for in totalDistributed for every admissible input.
        assertTrue(balDelta == distDelta && distDelta == toGive);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // owner (the deployer, i.e. this test contract) initializes the ledger
        c.XBornID();

        // a whitelisted actor claims through the payable entry
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 1 wei}(abi.encodeWithSignature("getTokens()"));

        if (ok) {
            // General rule: credited tokens are conserved against the ledger.
            // The owner's balance was set to totalDistributed by XBornID; any
            // successful distribution must raise totalDistributed by exactly
            // the amount actually credited to the recipient.
            assertTrue(
                c.balanceOf(address(this)) + c.balanceOf(actor) == c.totalDistributed()
            );
        } else {
            // if the claim reverted, the ledger must be untouched
            assertTrue(c.balanceOf(address(this)) + c.balanceOf(actor) == c.totalDistributed());
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function f(address a) public {
        assert(c.balanceOf(a) + c.totalDistributed() < c.totalSupply());
    }

    receive() external payable {}

    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function prove() public {
        c.XBornID();
        assert(c.balanceOf(address(this)) == c.totalDistributed());
    }
}
